
/* ===== PARTE 7 — TEXTURAS REAIS (Poly Haven, CC0) =====
   Chao: gravel_embedded_concrete_02. Parede: mixed_brick_wall.
   Bloco extra no fim. Se der erro, se desliga e o visual anterior continua. */
(function(){
'use strict';
try{
if(typeof THREE==='undefined'||typeof S==='undefined'||typeof walls==='undefined'||!walls.length)return;
const IMG_CHAO='data:image/jpeg;base64,';
const IMG_PAREDE='data:image/jpeg;base64,';
const load=src=>new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src=src});
const cv=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return[c,c.getContext('2d')]};

/* ---------- CHAO: troca a textura de detalhe pela foto do cascalho ---------- */
async function chao(){
 const im=await load(IMG_CHAO);
 const[c,g]=cv(512,512);g.drawImage(im,0,0,512,512);
 const d=g.getImageData(0,0,512,512),p=d.data;let mr=0,mg=0,mb=0;const n=p.length/4;
 for(let i=0;i<p.length;i+=4){mr+=p[i];mg+=p[i+1];mb+=p[i+2]}
 mr/=n;mg/=n;mb/=n;
 /* normaliza pela media: so o grao entra, sem escurecer o chao */
 for(let i=0;i<p.length;i+=4){
  p[i]=Math.max(0,Math.min(255,(1+(p[i]/mr-1)*1.25)*236));
  p[i+1]=Math.max(0,Math.min(255,(1+(p[i+1]/mg-1)*1.25)*236));
  p[i+2]=Math.max(0,Math.min(255,(1+(p[i+2]/mb-1)*1.25)*236))}
 g.putImageData(d,0,0);
 const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=8;
 const dp=S.children.find(o=>o.material&&o.material.uniforms&&o.material.uniforms.rad&&o.material.uniforms.c&&o.material.uniforms.map);
 if(!dp)return false;
 const m=dp.material;m.uniforms.map.value=t;
 m.fragmentShader=m.fragmentShader.replace('vW/5.','vW/1.8');
 m.needsUpdate=true;return true}

/* ---------- PAREDE: tijolo real, tom areia, com a sujeira antiga por cima ---------- */
async function parede(){
 const im=await load(IMG_PAREDE);
 const nw=walls[0].material;if(!nw||!nw.map)return false;
 const old=nw.map.image,oldB=nw.bumpMap?nw.bumpMap.image:null;
 /* tom: tira 35% da cor e esquenta para o tom areia da Dust 2 */
 const[tc,tg]=cv(512,512);tg.drawImage(im,0,0,512,512);
 const d=tg.getImageData(0,0,512,512),p=d.data;
 const[gc,gg]=cv(512,512);const gd=gg.createImageData(512,512);
 for(let i=0;i<p.length;i+=4){
  const l=.3*p[i]+.59*p[i+1]+.11*p[i+2];
  const r=p[i]*.65+l*.35,g=p[i+1]*.65+l*.35,b=p[i+2]*.65+l*.35;
  p[i]=Math.min(255,r*1.16);p[i+1]=Math.min(255,g*1.08);p[i+2]=Math.min(255,b*.93);
  const v=Math.max(0,Math.min(255,(l-110)*1.4+120));
  gd.data[i]=gd.data[i+1]=gd.data[i+2]=v;gd.data[i+3]=255}
 tg.putImageData(d,0,0);gg.putImageData(gd,0,0);
 const W=1024,T=W/3;
 const[wc,w]=cv(W,W),[bc,b]=cv(W,W);
 w.imageSmoothingQuality='high';b.imageSmoothingQuality='high';
 for(let x=0;x<3;x++)for(let y=0;y<3;y++){w.drawImage(tc,x*T,y*T,T+1,T+1);b.drawImage(gc,x*T,y*T,T+1,T+1)}
 /* sujeira, manchas e rachaduras do bloco 5 por cima */
 if(old){w.globalCompositeOperation='multiply';w.globalAlpha=.6;w.drawImage(old,0,0,W,W);w.globalAlpha=1;w.globalCompositeOperation='source-over'}
 if(oldB){b.globalCompositeOperation='multiply';b.globalAlpha=.5;b.drawImage(oldB,0,0,W,W);b.globalAlpha=1;b.globalCompositeOperation='source-over'}
 const mp=new THREE.CanvasTexture(wc),bp=new THREE.CanvasTexture(bc);
 [mp,bp].forEach(t=>{t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=8});
 nw.map=mp;nw.bumpMap=bp;nw.bumpScale=1.6;nw.needsUpdate=true;return true}

(async()=>{
 let a=false,b=false;
 try{a=await chao()}catch(e){console.error('[texturas-chao]',e)}
 try{b=await parede()}catch(e){console.error('[texturas-parede]',e)}
 console.log('[texturas-reais] chao:'+a+' parede:'+b)})();
}catch(e){try{console.error('[texturas-reais]',e)}catch(_){}}
})();
